// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestamp) public {
        vm.assume(timestamp > 0);
        vm.assume(blockNumber > 0);
        vm.roll(blockNumber);
        vm.warp(timestamp);
        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        assertTrue(success);
        uint256 balance = address(c).balance;
        if (blockNumber % 15 != 0) {
            assertEq(balance, 10 ether, "Reference should keep funds when block.number % 15 != 0");
        } else {
            assertEq(balance, 0, "Reference should transfer funds when block.number % 15 == 0");
        }
    }
}
